          <div className="absolute inset-0 bg-black/40" onClick={() => setDrawerOpen(false)} />
          <div className="absolute left-0 top-0 bottom-0 w-72 bg-white shadow-xl flex flex-col">
            <div className="w-full shrink-0 bg-navy-700 ios-safe-area-spacer" />
            <div className="h-16 flex items-center justify-between px-4 border-b border-slate-100">
              <div className="flex items-center gap-2">
                <img src={logo} alt="CRS Accounting" className="h-8 w-8 object-contain" />
                <span className="font-semibold text-navy-700">CRS Accounting</span>
              </div>
              <button onClick={() => setDrawerOpen(false)}><X size={22} /></button>
            </div>
            <CompanySwitcherBlock companies={companies} activeCompany={activeCompany} switchCompany={switchCompany} alwaysShowLabel />
            {availableProducts.length > 1 && (
              <div className="px-3 lg:px-4 py-3 border-b border-slate-100">
                <div className="text-[11px] font-semibold text-slate-400 uppercase mb-1.5">Product</div>
                <div className="space-y-1">
                  {availableProducts.map(product => (
                    <button
                      key={product}
                      onClick={() => switchProduct(product)}
                      className={`w-full text-left px-2.5 py-1.5 rounded-lg text-sm ${product === activeProduct ? 'bg-navy-600 text-white' : 'text-slate-600 hover:bg-slate-100'}`}
                    >
                      {PRODUCT_LABELS[product]}
                    </button>
                  ))}
                </div>
              </div>
            )}
            <nav className="flex-1 overflow-y-auto py-2" onClick={() => setDrawerOpen(false)}>
              {visibleNavItems.map(item => <NavItem key={item.to} {...item} alwaysShowLabel />)}
            </nav>
            <div className="mt-auto border-t border-slate-100 flex flex-col">
              <button onClick={signOut} className="flex items-center gap-3 px-5 py-4 text-sm text-slate-500">
                <LogOut size={18} /> Log Out
              </button>
              <div className="flex flex-col gap-1 px-5 py-4 text-[10px] text-slate-400 text-center bg-slate-50/50 border-t border-slate-100">
                <div className="flex justify-center gap-3">
                  <NavLink to="/data-security" onClick={() => setDrawerOpen(false)} className="hover:text-slate-600 transition-colors">Data Security</NavLink>
                  <NavLink to="/privacy" onClick={() => setDrawerOpen(false)} className="hover:text-slate-600 transition-colors">Privacy Policy</NavLink>
                </div>
                <div className="mt-2 text-[9px] leading-tight">
                  CRS Accounting is owned by<br/>
                  <span className="font-medium text-slate-500">CRS Central - A Unit of CRS Chauhan Private Limited.</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Main content column */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Mobile top bar */}
        <header className="md:hidden bg-white border-b border-slate-200 sticky top-0 z-30 flex flex-col">
          <div className="w-full shrink-0 bg-navy-700 ios-safe-area-spacer" />
          <div className="h-14 w-full flex items-center justify-between px-4 shrink-0">
          <button onClick={() => setDrawerOpen(true)}><Menu size={22} className="text-navy-700" /></button>
          <div className="flex flex-col items-center">
            <div className="flex items-center gap-2">
              <img src={logo} alt="" className="h-6 w-6 object-contain" />
              <span className="font-semibold text-navy-700 text-sm">{activeCompany?.name || 'CRS Accounting'}</span>
            </div>
            {availableProducts.length > 0 && (
              <span className="text-[10px] text-slate-400 -mt-0.5">{PRODUCT_LABELS[activeProduct]}</span>
            )}
          </div>
          <div className="w-6" />
          </div>
        </header>

        {/* Persistent "you are here" bar — visible on every page, every screen size */}
        <ActiveCompanyBar toggleSidebar={() => setSidebarExpanded(e => !e)} companies={companies} activeCompany={activeCompany} switchCompany={switchCompany} activeRole={activeRole} activeProduct={activeProduct} availableProducts={availableProducts} switchProduct={switchProduct} />

        {showInstallBanner && (
          <InstallBanner isIOS={isIOS} canInstall={canInstall} onInstall={promptInstall} onDismiss={dismissInstallBanner} />
        )}

        {backupFailed && (
          <div className="bg-red-600 text-white p-3 text-center text-sm font-medium shadow-md z-50 sticky top-0 flex items-center justify-center gap-2">
            <AlertTriangle size={18} />
            CRITICAL WARNING: The Nightly Database Backup failed on GitHub at {backupFailedDate}. Please check your GitHub Actions immediately.
          </div>
        )}
        <main className="flex-1 p-3 sm:p-4 md:p-6 lg:p-8 pb-20 md:pb-8 max-w-[1600px] w-full mx-auto">
          <Outlet />
        </main>
      </div>

      {/* Mobile bottom tab bar */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 flex justify-around py-1.5 z-30">
